#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Signing the Windows installers with SignPath Foundation: what only the maintainer can do.
# Run from the repository's folder: bash scripts/setup-windows-signing.sh
# Background: docs/code-signing.md, docs/research/windows-download-warnings.md (section 6).
# Values that aren't secret are remembered in .scratch/ (git-ignored) for a re-run; the API token
# goes only to GitHub, never to a file.
ENV_FILE="${ENV_FILE:-.scratch/windows-signing.env}"
mkdir -p "$(dirname "$ENV_FILE")"
REPO_URL="https://github.com/pablonification/edunex-plus"
SITE_URL="https://edunex-plus.arqilasp.com/"
POLICY_URL="$REPO_URL/blob/main/docs/code-signing.md"

TOTAL_STAGES=8

banner "Signing the Windows installers (SignPath Foundation)"

stage "Two-factor authentication on GitHub"
say "SignPath Foundation requires everyone who commits or approves releases to sign in to GitHub"
say "(and later SignPath) with two-factor authentication."
open_url "https://github.com/settings/security"
step "Under Two-factor authentication: if it says Enabled, you're done here."
step "Otherwise click Enable two-factor authentication and follow GitHub's steps."
note "Anyone else with write access to the repository needs it too."
pause "Press Enter once two-factor authentication is on"

stage "The code signing policy is live"
say "SignPath reviews the project's code signing policy, so it must be public before you apply:"
say "on the README, on the website's footer and install steps, and in each release's notes."
open_url "$POLICY_URL"
step "Check the page opens on GitHub (it does once the ci/windows-signing pull request is merged)."
open_url "$SITE_URL"
step "Check the website's footer has a 'Code signing policy' link (the site publishes from main)."
pause "Press Enter once both are live"

stage "Apply to SignPath Foundation"
say "Free code signing for open-source projects. It reviews the project; there's no ID check of you."
open_url "https://signpath.org/apply"
step "Project name: Edunex Plus. Repository: $REPO_URL"
step "Licence: MIT. Website: $SITE_URL"
step "Code signing policy: $POLICY_URL"
step "What it is, plainly: an unofficial desktop app by ITB students for ITB students; not made by"
step "  or connected to ITB or Cognisia. Built by GitHub Actions; Windows installers made by electron-builder."
step "Ask them two things in the form's notes, so a 'no' comes early rather than at release time:"
step "  1) Is signing the app's main program (Electron's executable, renamed) as our own file fine?"
step "  2) How big is the yearly size quota? Each release sends about 400 MB in two requests."
warn "SignPath decides at its discretion; reviews can take weeks. Re-run this wizard once it answers."
if ! confirm "Has SignPath Foundation accepted Edunex Plus?"; then
  note "Come back with: bash scripts/setup-windows-signing.sh (the stages before this one are quick to pass)."
  finish
  exit 0
fi

stage "SignPath: your account and organization"
open_url "https://app.signpath.io"
step "Sign in with the account SignPath set up for you, and turn on multi-factor authentication in your"
step "user profile (required by the Foundation's terms)."
step "Find the organization ID, a GUID. SignPath's docs don't say where it's shown: look in the address"
step "bar once you're in your organization (app.signpath.io/Web/<id>/...) or in the organization's settings."
ask SIGNPATH_ORGANIZATION_ID "Paste the organization ID:"
write_env SIGNPATH_ORGANIZATION_ID "$SIGNPATH_ORGANIZATION_ID"
set_var SIGNPATH_ORGANIZATION_ID "$SIGNPATH_ORGANIZATION_ID"

stage "SignPath: project, signing policy and GitHub"
step "Open Projects and the Edunex Plus project. Its slug is in the address and on its page."
ask SIGNPATH_PROJECT_SLUG "Project slug (Enter for edunex-plus):"
SIGNPATH_PROJECT_SLUG="${SIGNPATH_PROJECT_SLUG:-edunex-plus}"
step "Under Signing policies, find the release signing policy (with manual approval). Its slug:"
ask SIGNPATH_SIGNING_POLICY_SLUG "Signing policy slug (Enter for release-signing):"
SIGNPATH_SIGNING_POLICY_SLUG="${SIGNPATH_SIGNING_POLICY_SLUG:-release-signing}"
step "Under Trusted build systems, link the predefined 'GitHub.com' one to this project."
step "In the release signing policy, make yourself an approver, and allow tags (v*) as well as main."
write_env SIGNPATH_PROJECT_SLUG "$SIGNPATH_PROJECT_SLUG"
write_env SIGNPATH_SIGNING_POLICY_SLUG "$SIGNPATH_SIGNING_POLICY_SLUG"
# The workflow falls back to these names, so set the variables only when SignPath chose others.
if [[ "$SIGNPATH_PROJECT_SLUG" != edunex-plus ]]; then set_var SIGNPATH_PROJECT_SLUG "$SIGNPATH_PROJECT_SLUG"; fi
if [[ "$SIGNPATH_SIGNING_POLICY_SLUG" != release-signing ]]; then set_var SIGNPATH_SIGNING_POLICY_SLUG "$SIGNPATH_SIGNING_POLICY_SLUG"; fi
pause "Press Enter when the project, policy and GitHub link are set"

stage "SignPath: the two artifact configurations"
say "They tell SignPath which files in each upload to sign. They're in the repository, in .signpath/."
step "Project → Artifact configurations → New. Slug: windows-programs."
step "  Paste the contents of .signpath/windows-programs.xml and save."
step "New again. Slug: windows-installers. Paste .signpath/windows-installers.xml and save."
say "Then check them against real files, so the first release doesn't fail on a version number:"
open_url "$REPO_URL/actions/workflows/release.yml"
step "Run workflow (branch: main). When it finishes, download windows-programs-sample and app-win"
step "from the run's page."
step "In each configuration, upload a sample if SignPath offers it: windows-programs-sample.zip for the"
step "first, the two .exe files from app-win zipped together for the second. SignPath shows the product"
step "name and version it reads: they must match (version and windowsVersion in the XML comments)."
note "No sample upload? Then the first release is the test: a mismatch fails the signing request with"
note "a message naming the field, and re-running the job after fixing the XML in SignPath is enough."
pause "Press Enter once both configurations accept their sample"

stage "SignPath: the token GitHub Actions signs with"
step "Create a CI user (SignPath's account type for build systems; it signs in only with an API token)."
step "  Name it github-actions. SignPath's docs don't name the button: look under the organization's users."
step "Add that user to the release signing policy's Submitters (you stay its Approver)."
step "Generate the user's API token and copy it: SignPath shows a token once."
note "If you can't make a CI user, your own token works too: your name → My profile → API Token →"
note "Generate token. Then you're both submitter and approver."
ask_secret SIGNPATH_API_TOKEN "Paste the API token (hidden):"
set_secret SIGNPATH_API_TOKEN "$SIGNPATH_API_TOKEN"
unset SIGNPATH_API_TOKEN

stage "The first signed release"
say "From now on every version tag's Windows build is signed. To release:"
step "npm version <next version>, then git push --follow-tags (CONTRIBUTING.md, Releases)."
step "SignPath emails you twice while the Windows build waits: approve each request (45 minutes each)."
step "In the run's summary, 'Windows signatures (signpath)' lists each file signed by CN=SignPath Foundation."
step "Install it on a Windows PC, ideally one with Smart App Control on, and check the app opens."
step "If Smart App Control blocks part of it, note which file (Event Viewer → Applications and Services"
step "  Logs → Microsoft → Windows → CodeIntegrity → Operational) and open an issue."
step "Tell students in the release notes that Windows now names the publisher SignPath Foundation."
pause "Press Enter to finish"

finish
